import { Component, OnInit } from '@angular/core';
import { GameService, GameState } from '../../services/game.service';

@Component({
  selector: 'app-game',
  template: `
    <div class="game-container">
      <header class="game-header">
        <app-score></app-score>
        <app-rules-button></app-rules-button>
      </header>

      <main class="game-main">
        <div *ngIf="!gameState.showResult" class="choices-section">
          <h2 class="choices-title">Choose your weapon</h2>
          <div class="choices-grid">
            <app-choice-button 
              *ngFor="let choice of ['rock', 'paper', 'scissors']"
              [choice]="choice"
              (choiceSelected)="onChoiceSelected($event)">
            </app-choice-button>
          </div>
        </div>

        <div *ngIf="gameState.showResult" class="result-section">
          <app-result-display 
            [gameState]="gameState"
            (playAgain)="onPlayAgain()">
          </app-result-display>
        </div>
      </main>

      <app-rules-modal></app-rules-modal>
    </div>
  `,
  styleUrls: ['./game.component.scss']
})
export class GameComponent implements OnInit {
  gameState: GameState;

  constructor(private gameService: GameService) {
    this.gameState = {
      playerChoice: null,
      computerChoice: null,
      result: null,
      isPlaying: false,
      showResult: false
    };
  }

  ngOnInit(): void {
    this.gameService.gameState$.subscribe(state => {
      this.gameState = state;
    });
  }

  onChoiceSelected(choice: string): void {
    this.gameService.playGame(choice as any);
  }

  onPlayAgain(): void {
    this.gameService.resetGame();
  }
}
